/* Complete, engine-checked methods for Master Pyraminx, Kilominx and Ghost.
 * The tiny Master tables track pairs/triples, not complete configurations.
 * Kilominx reuses the common dodecahedral corner operations. Ghost uses the
 * exact cube-piece and oriented-center operations, not ordinary colors only. */
(function(){
'use strict';
const M=window.MASTER_GUIDE_DATA,C=window.EDGE_CRYSTAL_GUIDE_BUILDERS,S=window.SHAPE_GUIDES;
if(!M||!C||!S)throw Error('Load master-guide-data, edge-crystal-guides and shape-guides before addition-guides');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parse=s=>s.trim().split(/\s+/).filter(Boolean),inverse=s=>parse(s).reverse().map(t=>t.endsWith("'")?t.slice(0,-1):t+"'").join(' ');
const canonical=(a,mode)=>mode==='pair'?a.slice().sort().join('|'):[a.join('|'),[a[1],a[2],a[0]].join('|'),[a[2],a[0],a[1]].join('|')].sort()[0];
function sequence(puzzle,method,slots){
 if(puzzle==='kilominx')return C.sequence('crystal',method,slots);
 const d=puzzle==='masterpyraminx'&&M[method];
 if(!d||slots.length!==(d.mode==='pair'?2:3)||new Set(slots).size!==slots.length||slots.some(s=>!d.slots.includes(s)))return null;
 let path=d.paths[canonical(slots,d.mode)],core=d.core;
 if(path===undefined&&method==='center'){path=d.paths[canonical([slots[0],slots[2],slots[1]],d.mode)];core=inverse(core);}
 return path===undefined?null:{setup:inverse(path),core,restore:path};
}
const definitions=(puzzle,method)=>puzzle==='masterpyraminx'?M[method]:C.data.crystal[method];
function result(puzzle,method,slots){
 const s=sequence(puzzle,method,slots);if(!s)return'<p>Choose a different slot in each field.</p>';
 const effect=method==='flip'?'Flip the two selected midges in place.':method==='twist'?escape(slots[0])+' twists 120° clockwise and '+escape(slots[1])+' twists 120° counterclockwise, looking inward at each corner.':escape(slots.join(' → ')+' → '+slots[0])+'.';
 const protectedText=puzzle==='kilominx'?'Every unselected corner returns unchanged.':method==='wing'?'Every unselected piece returns unchanged.':method==='center'?'All midges, axials and tips return unchanged. Wings may move; they are the next stage.':'All unselected midges, axials and tips return unchanged. Centers and wings may move; solve them later.';
 return'<p><strong>'+effect+'</strong> '+protectedText+'</p>'+(s.setup?'<p>1. Set up: <code>'+escape(s.setup)+'</code></p>':'<p>1. No setup needed.</p>')+'<p>2. Work: <code>'+escape(s.core)+'</code></p>'+(s.restore?'<p>3. Restore: <code>'+escape(s.restore)+'</code></p>':'<p>3. No restore moves needed.</p>');
}
function builder(puzzle,method,title){
 const d=definitions(puzzle,method),base=d.base||d.seeds[0].base,labels=d.mode==='pair'?['First midge','Second midge']:d.mode==='ordered'?['Clockwise corner','Counterclockwise corner']:['From slot','To slot','Then to slot'];
 return'<fieldset class="addition-move-builder" data-addition-puzzle="'+puzzle+'" data-addition-method="'+method+'"><legend>'+title+'</legend><div class="fto-builder-fields">'+labels.map((label,i)=>'<label>'+label+'<select data-addition-slot>'+d.slots.map(slot=>'<option'+(slot===base[i]?' selected':'')+'>'+escape(slot)+'</option>').join('')+'</select></label>').join('')+'</div><div class="fto-builder-result" aria-live="polite">'+result(puzzle,method,base)+'</div></fieldset>';
}
const chooseCycle='<ol><li>Choose a piece outside its home. Set <strong>From slot</strong> to its current slot and <strong>To slot</strong> to its home.</li><li>For <strong>Then to slot</strong>, choose another misplaced slot, different from the first two. Do not choose a solved piece as a buffer.</li><li>Perform <strong>Set up → Work → Restore</strong> completely. At least the first piece reaches home; pieces outside the three selected slots return unchanged within the piece family being solved.</li><li>Reinspect and repeat. Ignore orientation until the next stage if one is listed.</li></ol>';
const masterpyraminx={
 title:'Master Pyraminx · solve the six midges, then centers and wings',
 intro:'A complete method for the four-layer tetrahedron. Align the vertex pieces, place and flip the midges, place the face centers, then cycle the twelve wings. The move builders provide a sequence for every pair or triple used by this method.',
 notation:[
  'The four fixed vertex letters are <strong>U, L, R and B</strong>. An ordinary capital moves the upper two layers including its tip; <strong>Uw, Lw, Rw and Bw</strong> move the upper three layers. Lowercase <strong>u, l, r, b</strong> move only one small tip.',
  'Every turn is 120° clockwise looking inward from the named vertex. A prime (′) reverses it. Two clockwise turns equal one inverse turn. Camera rotation does not rename any control. Read each displayed sequence from left to right.',
  'A <strong>midge</strong> is the two-color piece halfway along a tetrahedral edge. A <strong>wing</strong> is one of the two neighboring two-color pieces. <strong>UL midge</strong> lies on edge U–L; <strong>UL wing</strong> is its neighbor nearer U, whereas <strong>LU wing</strong> is nearer L. These two wing slots are different.',
  'Face-center names use the <em>opposite</em> vertex: <strong>U center</strong> is in the face opposite vertex U, at the bottom in the starting view. The target face colors are opposite U yellow, opposite L blue, opposite R red, opposite B green.',
  'Enable <strong>Piece labels</strong> and select a ring-map node to inspect its physical piece and <strong>home → current slot</strong>. Use those slot names in the builders. The colored stickers also identify its destination; the labels distinguish the two wings sharing a color pair.'
 ],
 steps:[
  {title:'Identify the five kinds of pieces',body:'<p>Each of the four faces has sixteen triangular stickers. The thirty rigid pieces are four tips, four three-color axials beneath the tips, six two-color midges, twelve two-color wings and four one-color face centers.</p><p>The center triangles <strong>can move between faces</strong> under wide turns. They are not fixed reference centers like those of a 3×3 cube. The axials stay at their vertices but can rotate. This is a four-layer Pyraminx mechanism, not the quarter-turn, shape-changing MasterMorphix.</p><p>The stages below deliberately use exact home identities. You need neither a recorded scramble nor a lucky intuitive insertion. All displayed operations have been checked on this game’s physical piece and sticker permutations.</p>'},
  {title:'1 · Align the four axials and the four tips',body:'<p>At each vertex, inspect the larger three-color piece immediately below its small tip. Use its ordinary capital control, <code>U</code>, <code>L</code>, <code>R</code> or <code>B</code>, until its three stickers face their target faces. At most two turns are needed. Ignore the wings moved by this operation.</p><p>Then use the matching lowercase control to align the small tip with that axial. Repeat at all four vertices. Each vertex has one absent face color; its other three colors must appear on the correct sides, not merely match one neighbor.</p><p>Every complete builder below preserves the axials and tips. They can move temporarily during Setup, but return after Restore.</p>'},
  {title:'2 · Put all six midges in their home edges',body:'<p>Find the middle of each three-piece edge strip. These six midges have distinct color pairs. Compare both colors with the two faces bordering the edge. Ignore which of the two stickers faces which side for now.</p>'+chooseCycle+builder('masterpyraminx','midge','Cycle three midges')+'<p>This operation may rearrange centers and wings; that is expected. An ordinary or wide turn produces an even permutation of midges, so a legally scrambled puzzle cannot finish this stage with exactly two midges exchanged. If it appears to, recheck the middle pieces and complete the previous Restore.</p>'},
  {title:'3 · Flip the reversed midges in pairs',body:'<p>Each midge is now in the correct edge, but its two stickers may face the wrong sides. Select any two reversed midges below and finish the sequence. Repeat until all six match both adjoining faces.</p>'+builder('masterpyraminx','flip','Flip two midges')+'<p>Every midge stays in its current edge after this complete operation. Only the two selected midges reverse. Legal moves preserve an even number of midge flips; a single reversed midge is not a final legal case. Leave the centers and wings for the next stages.</p>'},
  {title:'4 · Move the four face centers into place',body:'<p>Now inspect the one-color triangle at the center of each face. Remember that its label names the vertex opposite that face. For example, the yellow center belongs at <strong>U center</strong>.</p>'+chooseCycle+builder('masterpyraminx','center','Cycle three face centers')+'<p>There are only four center positions. Besides a solved arrangement, their even permutations consist of a three-cycle or two simultaneous exchanges. The same three-cycle builder handles both: for two exchanged pairs, choose three of the four wrong slots, perform the operation, then finish the three remaining wrong slots.</p><p>The solved midges, axials and tips are preserved. Wings may move. A center is a single-color equilateral triangle, so its in-place 120° orientation needs no separate stage.</p>'},
  {title:'5 · Finish the twelve wings',body:'<p>Every remaining wrong sticker belongs to a wing. Each midge has one wing on either side. The two matching-color wings are not interchangeable: their positions relative to the endpoints distinguish <strong>UL wing</strong> from <strong>LU wing</strong>. Use the home/current readout if the colored pair alone is ambiguous.</p>'+chooseCycle+builder('masterpyraminx','wing','Cycle three wings')+'<p>This builder preserves every other physical piece. A wing has no independent flip once it occupies its exact home slot: the tetrahedral geometry fixes its orientation there. Consequently there is no separate wing-flip stage.</p><p>All legal wing permutations are even. The last three wrong wings form one cycle; a supposed isolated pair usually means that two same-color wings were treated as interchangeable. Read their full ordered labels and check both stickers.</p>'},
  {title:'Check the four uniform faces',body:'<p>Each ring-map group should contain sixteen stickers of one face color, and the 3D view should show four uniform triangular faces. Look underneath as well. A wrong middle sticker calls for the midge stages; a wrong central triangle calls for the center stage; a wrong piece beside a midge calls for the wing stage.</p><p>The basic wing operation is especially short: <code>U Lw U′ Lw′</code> moves <strong>BL wing → UR wing → UL wing → BL wing</strong> and restores every other piece. The builder brings your chosen three slots into that arrangement and undoes the setup afterward. The longer midge and center operations use the same setup–work–restore idea.</p><p>Auto Solve can instead construct a verified solution directly from the current arrangement. Constrained Solver treats each selected sticker as part of a rigid piece: holding one side of a midge or wing can restrict the other side. Its protected nodes are restored at the end of a complete sequence, not necessarily during each intermediate turn.</p>'}
 ],
 sources:[
  {label:'Ruwix — Master Pyraminx geometry, layer notation and manual methods',url:'https://ruwix.com/twisty-puzzles/pyraminx-triangle-rubiks-cube/master-pyraminx/'},
  {label:'RobbieFish — Master Pyraminx Tutorial, illustrated piece types and layer turns',url:'https://afortmadeofbooks.blogspot.com/2024/12/master-pyraminx-tutorial.html'},
  {label:'Jaap Scherphuis — the underlying Pyraminx edge mechanism',url:'https://www.jaapsch.net/puzzles/pyraminx.htm'}
 ]
};
const kilominx={
 title:'Kilominx · place twenty corners, then orient them',
 intro:'The corners-only dodecahedral puzzle. A three-corner cycle and a paired twist are sufficient for every legal scramble; the builders below supply the setup for any selected slots.',
 notation:[
  'The twelve fixed face controls are <strong>A–L</strong>. Each letter is a 72° clockwise fifth-turn when looking inward at that face. A prime (′) reverses it; a 2 suffix means two fifth-turns, or 144°. Camera rotation changes your view, not the letters.',
  'A is the upper face, B–F surround it, G–K form the lower ring, and L is the bottom. The opposite pairs are <strong>A/L, B/I, C/J, D/K, E/G and F/H</strong>. Their twelve distinct colors provide the target scheme.',
  'A three-letter slot such as <strong>ABC</strong> is the corner where those faces meet. It is one physical piece with three stickers. It is not the instruction to perform A, B and C.',
  'Enable <strong>Piece labels</strong>, then click a ring-map node to see its physical piece’s <strong>home → current slot</strong> and sticker directions. The builders use those fixed slots. Finish <strong>Set up → Work → Restore</strong> before inspecting the result.'
 ],
 steps:[
  {title:'Establish the full color frame',body:'<p>A Kilominx has twenty three-color corners and no separately movable edge or face-center pieces. A face contains five corner stickers. This flat-faced version has the same corner action as a Megaminx and the same mechanism-level solving problem as the Impossiball/Flowerminx family.</p><p>Use the displayed twelve-face scheme or the home labels to distinguish each corner by all three of its colors. Do not invent a new neighboring-color order as you solve one face: with no fixed centers, a single completed face does not by itself determine the entire dodecahedron’s color frame.</p><p>The next two stages give a complete fixed-frame method. They deliberately preserve previously completed pieces after each full sequence, so you can stop at a stage boundary and resume without the move journal.</p>'},
  {title:'1 · Put the twenty corners in their home slots',body:'<p>First solve positions and ignore twists. A corner belongs at the unique slot whose three face colors match its three stickers, in any orientation.</p>'+chooseCycle+builder('kilominx','corner','Cycle three Kilominx corners')+'<p>Only the chosen three corners change after the complete sequence; their twists may also change. Leave that for the next stage. This fixes at least one misplaced corner each time, without displacing any already correctly placed corner.</p><p>Every face turn cycles five corners and therefore has even permutation parity. An isolated exchange of two corners is impossible. The final misplaced pieces are a three-cycle, or several cycles that the same procedure reduces. If only two appear wrong, check all three colors and whether the preceding Restore was finished.</p>'},
  {title:'2 · Orient the corners in pairs',body:'<p>With all twenty pieces at home, inspect each corner’s three stickers. A wrong corner needs a 120° twist about its own diagonal. Look directly inward toward that corner to determine the direction.</p><p>Choose one twisted corner and put it in the field for the direction that corrects it. Put another twisted corner in the opposite field. The first becomes correct; the second becomes correct or retains a twist that you repair with another partner. Continue until every sticker faces its own face.</p>'+builder('kilominx','twist','Twist two Kilominx corners')+'<p>This keeps every corner in place and preserves all unselected corners exactly. One clockwise twist equals two counterclockwise twists. If two corners both appear to need the same direction, use either as the partner: it absorbs the extra twist. Reinspect and repeat with another unfinished corner.</p><p>The sum of corner twists is zero modulo three in every legal state. Therefore the process cannot finish with one twisted corner. There is no edge-flip or center stage.</p>'},
  {title:'Verify all twelve faces',body:'<p>Every face must show five matching colors, including the lower ring and bottom. A correctly placed corner can still put two or all three stickers on wrong faces; inspect orientation separately from position.</p><p>These two operations are the corner part of the dodecahedral method also used for Pyraminx Crystal, but Kilominx has no edges to finish afterward. The setup tables cover every three-corner cycle and every ordered pair of opposite twists. Their purpose is dependable local control, not globally shortest move sequences.</p><p>Constrained Solver works on individual sticker nodes. All three nodes on a corner belong to one rigid piece, and corner parity and twist conservation still apply. An unavailable isolated swap may become possible only when other corners are allowed to participate. Auto Solve uses the current legal arrangement and does not need a recorded scramble.</p>'}
 ],
 sources:[
  {label:'Jaap Scherphuis — Impossiball / Flowerminx: corner-only minx mechanism and solution',url:'https://www.jaapsch.net/puzzles/impossi.htm'},
  {label:'J. A. Storer — Kilominx collection record and equivalence to Impossiball',url:'https://www.cs.brandeis.edu/~storer/JimPuzzles/ZPAGES/zzzKilominx.html'},
  {label:'Jaap Scherphuis — Megaminx piece structure and methods',url:'https://www.jaapsch.net/puzzles/megaminx.htm'}
 ]
};
// The exact cube-piece builders already used by the polyhedral shape mods
// remain applicable in the Ghost's aligned mechanism frame. No extra tables.
const ghostStages=S.rhombic.steps.slice(2,-1).map(step=>({...step}));
const centerIndex=ghostStages.findIndex(step=>step.title.includes('Align the six'));
if(centerIndex>=0)ghostStages[centerIndex]={...ghostStages[centerIndex],body:ghostStages[centerIndex].body.replace('When the physical colors and silhouette match, any remaining invisible orientation can be ignored.','The asymmetric Ghost centers have a visible direction. Restore their full reference orientation; color alone can conceal a turned center.')};
const ghost={
 title:'Ghost Cube · solve the mechanism, then restore the shell',
 intro:'An angular 3×3 shape modification with misaligned layers. Start with the colored version to learn its pieces; Mirror mode removes the colors for the shape-only challenge. The full method also repairs directional centers.',
 notation:[
  'The fixed <strong>U R F D L B</strong> controls name the six faces of the <em>aligned internal 3×3 mechanism</em>. They do not name the flat exterior faces of the solved shell. Each move is a 90° clockwise turn viewed from outside that mechanism face; a prime reverses it and 2 is a half-turn.',
  'The game automatically aligns the offset layers before ordinary moves, and restores their offset resting angles after the exact mechanism is solved. Those visible alignment motions are part of presenting the shape, not additional quarter-turn instructions to enter.',
  'One-letter labels identify the six mechanism centers. Two letters, such as UF, identify the twelve edges; three letters, such as UFR, identify the eight corners. Count mechanism attachments, not the number of polygonal exterior patches: an irregular physical piece can cross more than one shell face.',
  'For the learning method, leave <strong>Mirror mode</strong> off, enable <strong>Piece labels</strong>, and select a node to inspect its <strong>home → current slot</strong> and orientation. Follow the fixed labels after orbiting the camera. Finish every builder’s Set up, Work and Restore.'
 ],
 steps:[
  {title:'Understand the two frames',body:'<p>The smooth solved cube is the <strong>shell frame</strong>. Its flat exterior faces are cut obliquely and its upper and lower layers sit at deliberate offsets. The regular quarter-turn axes belong to a different, aligned <strong>mechanism frame</strong>. A correctly aligned mechanism can therefore look jagged until the resting layer offsets are restored.</p><p>This game uses an original polyhedral Ghost-style construction, not measured dimensions of a particular commercial edition. It retains the defining ideas: straight cuts, unequal angular pieces, a 3×3 mechanism, offset layers and visibly directional centers.</p><p>The six exterior colors are learning aids. They describe the solved shell faces, not a conventional one-sticker-per-mechanism-face cube coloring. Use the home labels for the complete reference method below instead of blindly applying an ordinary “white cross” recipe to the shell.</p>'},
  {title:'1 · Identify pieces and their destinations',body:'<p>Turn on Piece labels in colored mode. Click any sticker of a physical piece to read its mechanism home and current slot. For example, <strong>UF → BR</strong> means the UF edge belongs at UF but currently occupies BR. The orientation readout distinguishes a flipped edge, a twisted corner and a rotated center.</p><p>Use the exact piece identities while learning. A Ghost piece may have the right color visible but still have an incorrect slope, thickness, position or in-place rotation. Several polygons can belong to the same rigid piece. The ring map shows these polygons’ colors using abstract oriented attachments to their pieces; it does not reproduce their unequal shapes or measured surface centroids. These attachments form 168 possible addresses, of which 61 are occupied. A constrained exchange swaps two occupied attachment addresses, while the held attachments return to their original addresses. A held attachment determines its piece’s full orientation, including an irregular center. Empty addresses are never selectable.</p><p>There are twelve mechanism edges, eight corners and six centers. The following stages solve those pieces in that order. Centers remain at their axes throughout ordinary turns, but their orientation matters at the end.</p>'},
  ...ghostStages,
  {title:'7 · Restore the offset cube and check every seam',body:'<p>Once the mechanism pieces and directional centers are fully restored, the game returns the upper and lower layers to their offset resting angles. The exterior should form one smooth cube again.</p><p>Inspect all six faces and the silhouette from several viewpoints. If a surface remains stepped, do not force an extra shell-face turn: check the corresponding edge flip, corner twist or center rotation in the mechanism frame. A center can have the right position and color while its unequal outline still points the wrong way.</p><p>Auto Solve verifies the full modeled piece poses and uses the same legal quarter-turn mechanism. It includes the directional center repair that an ordinary color-only 3×3 solution may omit. The visual docking motion is completed after the exact solved state is reached.</p>'},
  {title:'Advanced · solve by shape in Mirror mode',body:'<p>Enable <strong>Mirror mode</strong> in the 3D panel to remove all face colors. The ring map is hidden in this mode. The toggle changes the display, not the current scramble.</p><p>Identify each piece by its complete silhouette, surface slopes and seam lengths. A center is attached to one turning axis, an edge meets two mechanism layers, and a corner meets three. Use the six centers’ shape and orientation as landmarks. Match an edge to the two neighboring structures it joins and a corner to all three.</p><p>The same placement, paired-flip, paired-twist and center-orientation stages apply, but you now infer home and orientation from geometry. Do not expect the shell to be cubic during the solve: keep the mechanism aligned, complete the piece stages, and let the final resting offsets close the shell. You may return to colored mode to inspect an unfamiliar piece without changing its state.</p><p>Unlike shape modifications with interchangeable symmetric pieces, these asymmetric shapes are intended to identify the exact fitted arrangement. Center direction is part of that shape goal; do not stop at a color-only or position-only match.</p>'}
 ],
 sources:[
  {label:'Recent Toys / Meffert’s — Ghost Cube, official puzzle description',url:'https://recenttoys.com/ghost-cube-m-4/'},
  {label:'J. A. Storer — Ghost Cube, Adam G. Cowan design and photographs',url:'https://www.cs.brandeis.edu/~storer/JimPuzzles/ZPAGES/zzzGhostCube.html'},
  {label:'TwistyPuzzles Museum — Ghost Cube original design record',url:'https://twistypuzzles.com/app/museum/museum_showitem.php?pkey=1946'},
  {label:'Jaap Scherphuis — Rubik’s Cube modifications and oriented centers',url:'https://www.jaapsch.net/puzzles/cubevari.htm'}
 ]
};
window.ADDITION_GUIDES={masterpyraminx,kilominx,ghost};
window.ADDITION_GUIDE_BUILDERS=Object.freeze({sequence,inverse,canonical,data:{masterpyraminx:M,kilominx:C.data.crystal}});
document.addEventListener('change',event=>{const target=event.target;if(!target||!target.closest)return;const box=target.closest('.addition-move-builder');if(!box)return;box.querySelector('.fto-builder-result').innerHTML=result(box.dataset.additionPuzzle,box.dataset.additionMethod,Array.from(box.querySelectorAll('[data-addition-slot]'),e=>e.value));});
})();
